<template>
  <section class="component-catalog sf-ui" :data-theme="theme" :data-reduce-motion="reduceMotion?'true':'false'" :data-reduce-transparency="reduceTransparency?'true':'false'" :style="{'--sf-scale':largeText?'1.3':'1'}">
    <header class="catalog-heading"><div><h2>交互组件工作台</h2><p>已有稿件继续对照 Figma；新增状态依据 Apple 指南补全。所有控件可直接操作。</p></div><sf-badge tone="accent">{{ componentCount }} 个基础组件</sf-badge></header>
    <div class="catalog-preferences"><label for="catalog-theme">外观</label><select id="catalog-theme" v-model="theme"><option value="light">浅色</option><option value="dark">深色</option></select><sf-switch v-model="largeText" label="放大文字"/><sf-switch v-model="reduceMotion" label="减少动态效果"/><sf-switch v-model="reduceTransparency" label="减少透明度"/></div>
    <sf-segmented-control v-model="category" :items="categories" label="Component category" appearance="grouped"/>
    <div class="catalog-grid">
      <article v-if="show('navigation')" class="catalog-example" data-component="SfHeader"><h3>顶部导航</h3><p class="catalog-source">原层级与返回字符 · 补齐触控区域</p><sf-header title="Plan & Benefits" @back="notify('Back action emitted')"/><sf-header title="Today’s plan" glass @back="notify('Back action emitted')"><template #trailing><button type="button" class="sf-icon-button" aria-label="More plan options" @click="notify('More action emitted')"><sf-icon name="more"/></button></template></sf-header></article>
      <article v-if="show('navigation')" class="catalog-example" data-component="SfSegmentedControl"><h3>分段切换</h3><p class="catalog-source">V3 结构 · HIG 补全键盘与禁用状态</p><sf-segmented-control v-model="section" :items="sections" label="Progress sections"/><p class="catalog-value">Selected: {{ section }}</p><sf-segmented-control v-model="density" :items="densities" label="Display density" appearance="grouped"/></article>
      <article v-if="show('input')" class="catalog-example" data-component="SfField"><h3>表单输入</h3><p class="catalog-source">HIG 补全 · 持续标签和错误反馈</p><sf-field v-model="displayName" label="Display name" autocomplete="name" help="Your name appears on your profile."/><sf-field v-model="password" label="Password" type="password" autocomplete="new-password"/><sf-field v-model="email" label="Recovery email" type="email" :error="email&&!email.includes('@')?'Enter a valid email address.':''"/><sf-field value="Connected device" label="Read-only value" readonly/><sf-field value="Unavailable" label="Disabled value" disabled/></article>
      <article v-if="show('input')" class="catalog-example" data-component="SfSearchField"><h3>搜索与多行输入</h3><p class="catalog-source">HIG 补全 · 清除搜索保留其他输入</p><sf-search-field v-model="search" label="Search workouts" placeholder="Search workouts" @search="notify('Search: '+search)"/><p class="catalog-value">{{ search?'Query: '+search:'No search query' }}</p><sf-field v-model="notes" label="Plan notes" multiline placeholder="What would you like to work on?" help="Your text remains when another control changes."/></article>
      <article v-if="show('input')" class="catalog-example" data-component="SfSwitch"><h3>开关与选择</h3><p class="catalog-source">HIG 补全 · 标签和原生表单语义</p><sf-switch v-model="reminders" label="Workout reminders" description="A reminder before your scheduled session."/><sf-switch :value="false" label="Unavailable setting" disabled/><sf-choice v-model="updates" label="Receive training updates" description="You can change this preference later."/><fieldset class="catalog-fieldset"><legend>Training pace</legend><sf-choice v-model="pace" type="radio" name="training-pace" option="gentle" label="Gentle"/><sf-choice v-model="pace" type="radio" name="training-pace" option="moderate" label="Moderate"/></fieldset></article>
      <article v-if="show('input')" class="catalog-example" data-component="SfSlider"><h3>数值控件</h3><p class="catalog-source">HIG 补全 · 边界和键盘输入</p><sf-slider v-model="effort" label="Effort" :min="1" :max="10" unit=" / 10" help="Use arrow keys to change the value."/><sf-stepper v-model="sessions" label="Sessions per week" :min="1" :max="7"/></article>
      <article v-if="show('feedback')" class="catalog-example" data-component="SfFeedback"><h3>空状态与错误</h3><p class="catalog-source">HIG 补全 · 明确下一步和重试</p><sf-feedback tone="empty" title="No active plan" description="Your current activities are still available." action="Choose a plan" @action="notify('Choose-plan action emitted')"/><sf-feedback tone="error" title="Couldn’t load your data" description="Your saved data has not changed." action="Try again" @action="notify('Retry action emitted')"/></article>
      <article v-if="show('feedback')" class="catalog-example" data-component="SfSkeleton"><h3>加载与状态标签</h3><p class="catalog-source">HIG 补全 · 颜色之外也表达状态</p><sf-skeleton image label="Loading workout preview"/><div class="catalog-badges"><sf-badge>Free</sf-badge><sf-badge tone="accent">Current plan</sf-badge><sf-badge tone="success">Saved</sf-badge><sf-badge tone="warning">Pending</sf-badge><sf-badge tone="danger">Failed</sf-badge></div><sf-button @click="notify('Your changes have been saved.')">Show notification</sf-button></article>
      <article v-if="show('layout')" class="catalog-example" data-component="SfCard"><h3>内容容器与身份</h3><p class="catalog-source">HIG 补全 · 动态数据通过 props 传入</p><sf-card title="Your profile"><template #accessory><sf-avatar :name="displayName||'SunnyFit'"/></template><p class="catalog-copy">{{ displayName||'SunnyFit' }}</p><template #footer><sf-menu-row label="Edit profile" description="Component event preview" @click="notify('Edit-profile action emitted')"/></template></sf-card><sf-card title="Included services" tone="membership"><template #accessory><sf-badge tone="accent">Premium</sf-badge></template><p class="catalog-copy">8 of 30 coach replies left</p><sf-usage-meter :remaining="8" :total="30" label="Preview included replies remaining"/></sf-card></article>
      <article v-if="show('layout')" class="catalog-example" data-component="SfSheet"><h3>弹层与确认</h3><p class="catalog-source">HIG 补全 · 统一关闭和焦点契约</p><sf-button @click="openPreferences">Open preference sheet</sf-button><sf-button @click="openBusy">Open processing sheet</sf-button><sf-button @click="dialog=true">Open discard dialog</sf-button><p class="catalog-copy">弹层支持键盘、遮罩、下拉和中/大高度。未保存内容与处理中状态会阻止直接关闭。</p></article>
    </div>
    <article v-if="show('layout')||show('navigation')" class="catalog-example catalog-example--home" data-component="V3Home"><h3>正式 V3 首页与共用业务组件</h3><p class="catalog-source">正式文件 7590:5619 · 导航 / 课程 / 计划 / 数据卡片 / 照片空状态</p><home-components-showcase @action="notify('Preview action: '+$event)"/></article>
    <article v-if="show('layout')||show('navigation')" class="catalog-example catalog-example--home" data-component="V3Pages"><h3>页面接入与计划状态</h3><p class="catalog-source">共用页面框架、背景、Go 按钮、阶段、五日预览、Coach 课程卡和训练轮播。以下是可操作的组件参考场景。</p><page-components-showcase @action="notify('Preview action: '+$event)"/></article>
    <article v-if="show('layout')||show('input')" class="catalog-example catalog-example--home" data-component="SfMessageComposer"><h3>聊天组件与输入状态</h3><chat-components-showcase @action="notify('Preview action: '+$event)"/></article>
    <div class="catalog-notification"><sf-toast v-model="toast" :message="toastMessage"/></div>
    <sf-sheet v-model="sheet" title="Plan preferences" :busy="busy" :dismissible="!dirty" detent="medium" @dismiss-blocked="blocked"><p class="catalog-copy">A scoped task returns to the same page after saving or canceling.</p><sf-field v-model="sheetNotes" label="Preference notes" multiline/><sf-switch v-model="busy" label="Simulate processing" description="Closing is blocked while processing."/><p v-if="modalHint" class="catalog-modal-hint" role="status">{{ modalHint }}</p><p v-for="n in 4" :key="n" class="catalog-copy">Content section {{ n }}. The body scrolls independently while the action area remains visible.</p><template #footer><div class="catalog-sheet-actions"><sf-button :disabled="busy" @click="discard">Discard changes</sf-button><sf-button :disabled="busy" @click="save">Save preferences</sf-button></div></template></sf-sheet>
    <sf-dialog v-model="dialog" title="Discard local draft?" description="This only affects the component preview. Your account and saved workouts stay available." confirm-label="Discard" destructive @confirm="discardDialog"/>
  </section>
</template>
<script>
import {SfHeader,SfIcon,SfSegmentedControl,SfField,SfSearchField,SfSwitch,SfChoice,SfSlider,SfStepper,SfFeedback,SfSkeleton,SfBadge,SfButton,SfCard,SfAvatar,SfMenuRow,SfUsageMeter,SfToast,SfSheet,SfDialog} from '@/design-system'
import HomeComponentsShowcase from './HomeComponentsShowcase'
import PageComponentsShowcase from './PageComponentsShowcase'
import ChatComponentsShowcase from './ChatComponentsShowcase'
export default {name:'ComponentCatalog',components:{HomeComponentsShowcase,PageComponentsShowcase,ChatComponentsShowcase,SfHeader,SfIcon,SfSegmentedControl,SfField,SfSearchField,SfSwitch,SfChoice,SfSlider,SfStepper,SfFeedback,SfSkeleton,SfBadge,SfButton,SfCard,SfAvatar,SfMenuRow,SfUsageMeter,SfToast,SfSheet,SfDialog},data(){return {componentCount:41,theme:'light',largeText:false,reduceMotion:false,reduceTransparency:false,category:'all',categories:[{value:'all',label:'All'},{value:'navigation',label:'Navigation'},{value:'input',label:'Input'},{value:'feedback',label:'Feedback'},{value:'layout',label:'Layout'}],section:'plans',sections:[{value:'plans',label:'Plans'},{value:'tasks',label:'Daily Tasks'},{value:'challenge',label:'Challenges'},{value:'soon',label:'Soon',disabled:true}],density:'comfortable',densities:[{value:'comfortable',label:'Comfortable'},{value:'compact',label:'Compact'}],displayName:'Alex Chen',password:'demo-password',email:'invalid-email',search:'',notes:'',reminders:true,updates:false,pace:'gentle',effort:4,sessions:3,toast:false,toastMessage:'',sheet:false,busy:false,sheetNotes:'',savedNotes:'',modalHint:'',dialog:false}},computed:{dirty(){return this.sheetNotes!==this.savedNotes}},methods:{show(category){return this.category==='all'||this.category===category},notify(message){this.toastMessage=message;this.toast=true},openPreferences(){this.busy=false;this.modalHint='';this.sheet=true},openBusy(){this.busy=true;this.modalHint='Processing: use the switch to finish the simulation.';this.sheet=true},blocked(){this.modalHint=this.busy?'Processing is still in progress.':'You have unsaved changes. Save or discard them before closing.'},save(){this.savedNotes=this.sheetNotes;this.sheet=false;this.notify('Preferences saved in this preview.')},discard(){this.sheetNotes=this.savedNotes;this.sheet=false},discardDialog(){this.notes='';this.dialog=false;this.notify('Local draft discarded.')}}}
</script>
<style>
.component-catalog{margin-bottom:22px;padding:22px;border-radius:18px;border:1px solid var(--sf-border);background:var(--sf-page);color:var(--sf-text);font-family:var(--sf-font-family)}.catalog-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:14px}.catalog-heading h2{font-size:22px;line-height:1.35;margin:0 0 8px}.catalog-heading p{margin:0;color:var(--sf-text-secondary);font-size:14px;line-height:1.7}.catalog-preferences{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin:20px 0}.catalog-preferences select{min-height:44px;padding:8px 12px;background:var(--sf-surface-solid);color:var(--sf-text);border:1px solid var(--sf-border);border-radius:12px;font:inherit}.catalog-preferences .sf-switch-row{gap:8px}.catalog-preferences .sf-switch-row strong{font-size:14px}.catalog-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:20px}.catalog-example{min-width:0;background:var(--sf-surface-solid);border:1px solid var(--sf-border);border-radius:20px;padding:18px}.catalog-example>h3{font-size:16px;margin:0 0 5px;line-height:1.5}.catalog-source{font-size:12px;color:var(--sf-text-secondary);margin:0 0 18px;line-height:1.6}.catalog-example>.sf-header,.catalog-example>.sf-field,.catalog-example>.sf-card,.catalog-example>.sf-feedback,.catalog-example>.sf-button{margin-bottom:14px}.catalog-value{font-size:13px;color:var(--sf-text-secondary);overflow-wrap:anywhere}.catalog-fieldset{border:0;padding:0;margin:14px 0}.catalog-fieldset legend{font-size:14px;color:var(--sf-text-secondary)}.catalog-badges{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}.catalog-copy{font-size:calc(15px * var(--sf-scale));line-height:1.6;color:var(--sf-text-secondary)}.catalog-notification{position:fixed;bottom:22px;right:22px;z-index:1900;max-width:min(390px,calc(100vw - 32px))}.catalog-sheet-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px}.catalog-sheet-actions .sf-button{min-height:48px;font-size:15px}.catalog-modal-hint{font-size:14px;line-height:1.5;color:var(--sf-danger);padding:12px;background:var(--sf-page);border-radius:12px}.component-catalog .sf-modal__body>.sf-field{margin-bottom:18px}
@media(max-width:1050px){.catalog-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.component-catalog{padding:16px}.catalog-grid{grid-template-columns:1fr}.catalog-heading{flex-direction:column}.catalog-preferences{gap:10px}.catalog-preferences .sf-switch-row{width:100%;justify-content:space-between}}
</style>
